#!/bin/bash
cd "$(dirname "$0")"
[ -n "${KEEP_STATE:-}" ] || rm -f state.json cast-state.json results-*.json shots/*.png outbox.jsonl progress.jsonl
ALL="s1-owner-signup s2-fleet-operator s3-job-lifecycle s4-now-direct s5-cab s6-owner-safety s7-smoke s8-ops s9-messaging s10-operator-onboard s11-skeletons s12-admin s13-accounts s14-mobile-operator s15-whatsapp-prefs s16-forgot-password s17-uploads s18-uploads-more s19-auth-spinners s20-owner-operator s21-doc-review s22-whatsapp-trial s23-guest-home s24-guest-post-job s25-app-gap-checks s26-one-free-plan s27-owner-ids s28-profile-photos s29-compulsory-docs s30-one-verification s31-job-visibility s32-job-email s33-market-switch s34-client-fixes s35-face-camera s36-client-points-nov12 s37-login-landing s38-profile-phone s39-client-test-nov16"
for s in ${STAGES:-$ALL}; do
  echo "================ $s"
  MOCK_OUTBOX="$PWD/outbox.jsonl" E2E_SEND_GRID_SENDER=simbatasker.noreply@yopmail.com LOGISTICS_WA_INVITE_TEMPLATE_SID=HXe2e0000000000000000000000invite LOGISTICS_WA_SOS_TEMPLATE_SID=HXe2e000000000000000000000000sos LOGISTICS_WA_DOC_EXPIRY_TEMPLATE_SID=HXe2e00000000000000000000docexp LOGISTICS_WA_QUOTE_TEMPLATE_SID=HXe2e0000000000000000000000quote LOGISTICS_WA_JOB_STATUS_TEMPLATE_SID=HXe2e000000000000000000jobstatus LOGISTICS_WA_JOB_PIN_TEMPLATE_SID=HXe2e00000000000000000000jobpin LOGISTICS_WA_NEW_JOB_TEMPLATE_SID=HXe2e00000000000000000000newjob LOGISTICS_WA_ACCOUNT_STATUS_TEMPLATE_SID=HXe2e0000000000000000accountstatus LOGISTICS_WA_DOC_REVIEW_TEMPLATE_SID=HXe2e0000000000000000000docreview LOGISTICS_WA_TRIAL_REMINDER_TEMPLATE_SID=HXe2e000000000000000trialreminder LOGISTICS_WA_BOOKING_REMINDER_TEMPLATE_SID=HXe2e00000000000000bookingreminder LOGISTICS_WA_FLEET_SUMMARY_TEMPLATE_SID=HXe2e000000000000000000fleetsummary LOGISTICS_WA_LOCATION_CHECK_TEMPLATE_SID=HXe2e00000000000000000locationcheck LOGISTICS_WA_TRIAL_DAYS=60 LOGISTICS_TEST_PAID_PLAN_ENABLED=true LOGISTICS_TEST_ACCOUNTS_ENABLED=true SEND_GRID_API_KEY=SG.e2e-fake SEND_GRID_SENDER=simbatasker.noreply@yopmail.com ACCOUNT_SID=ACe2e00000000000000000000000000000 AUTH_TOKEN=e2e-fake TWILIO_ACCOUNT_SID=ACe2e00000000000000000000000000000 TWILIO_AUTH_TOKEN=e2e-fake LOGISTICS_SMS_ENABLED=true LOGISTICS_WEB_URL=https://localhost:3001 timeout ${STAGE_TIMEOUT:-900} node $s.js 2>&1 | grep -v -i deprecation
done
node -e '
const fs=require("fs");let p=0,f=0;const fails=[];
for(const x of fs.readdirSync(".").filter(n=>n.startsWith("results-"))){const r=JSON.parse(fs.readFileSync(x));for(const c of r){c.ok?p++:(f++,fails.push(x+": "+c.section+" :: "+c.label))}}
console.log("\nTOTAL",p,"passed,",f,"failed");fails.forEach(l=>console.log("  FAIL",l));'
